import{_ as r,a0 as p,w as s,s as d,I as i,x as t,a1 as o,A as l,ao as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"年輕人，你為啥使用 linux | LCTT x X-CMD","titleTemplate":false,"description":"年輕人，你為啥使用 linux | LCTT (201603) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"年輕人，你為啥使用 linux | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"年輕人，你為啥使用 linux | LCTT (201603) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201603/20150820 Why did you start using Linux","title":"年輕人，你為啥使用 linux","tag":"201603","desc":""},"relativePath":"201603/20150820 Why did you start using Linux.md","filePath":"[post].md"}'),x={name:"201603/20150820 Why did you start using Linux.md"};function L(a,n,w,m,g,b){const u=p("Link");return s(),d("div",null,[n[28]||(n[28]=i("h1",{id:"年輕人-你為啥使用-linux",tabindex:"-1"},[t("年輕人，你為啥使用 linux "),i("a",{class:"header-anchor",href:"#年輕人-你為啥使用-linux","aria-label":"Permalink to “年輕人，你為啥使用 linux”"},"​")],-1)),n[29]||(n[29]=i("h3",{id:"當初你為何使用-linux",tabindex:"-1"},[t("當初你為何使用 Linux？ "),i("a",{class:"header-anchor",href:"#當初你為何使用-linux","aria-label":"Permalink to “當初你為何使用 Linux？”"},"​")],-1)),n[30]||(n[30]=i("p",null,"Linux 越來越流行，很多 OS X 或 Windows 用户都轉移到 Linux 陣營了。但是你知道是什麼讓他們開始使用 Linux 的嗎？一個 Reddit 用户在網站上問了這個問題，並且得到了很多有趣的回答。",-1)),n[31]||(n[31]=i("p",null,"一個名為 SilverKnight 的用户在 Reddit 的 Linux 版塊上問了如下問題：",-1)),i("blockquote",null,[n[1]||(n[1]=i("p",null,"我知道這個問題肯定被問過了，但我還是想聽聽年輕一代使用 Linux 的原因，以及是什麼讓他們堅定地成為 Linux 用户。",-1)),n[2]||(n[2]=i("p",null,"我無意阻止大家講出你們那些精彩的 Linux 故事，但是我還是對那些沒有經歷過什麼精彩故事的新人的想法比較感興趣。",-1)),n[3]||(n[3]=i("p",null,"我27歲，半吊子 Linux 用户，這些年裝過不少發行版，但沒有投入全部精力去玩 Linux。我正在找更多的、能讓我全身心投入到 Linux 潮流的理由，或者説激勵。",-1)),i("p",null,[o(u,{href:"https://www.reddit.com/r/linux/comments/3hb2sr/question_for_younger_users_why_did_you_start/"},{default:l(()=>[...n[0]||(n[0]=[t("詳見 Reddit",-1)])]),_:1})])]),n[32]||(n[32]=i("p",null,"以下是網站上的回覆：",-1)),i("blockquote",null,[n[5]||(n[5]=e("<p><strong>DoublePlusGood</strong>：我12歲開始使用 Backtrack（現在改名為 Kali），因為我想成為一名黑客（LCTT 譯註：原文“1337 haxor”，1337 是 leet 的火星文寫法，意為&#39;火星文&#39;，haxor 為 hackor 的火星文寫法，意為&#39;黑客&#39;，另一種寫法是 1377 h4x0r，滿滿的火星文文化）。我現在一直使用 ArchLinux，因為它給我無限自由，讓我對我的電腦可以為所欲為。</p><p><strong>Zack</strong>：我記得是12、3歲的時候使用 Linux，現在15歲了。</p><p>我11歲的時候就對 Windows XP 感到不耐煩，一個簡單的功能，比如關機，TMD 都要讓我耐心等着它慢慢完成。</p><p>在那之前幾個月，我在 freenode IRC 聊天室參與討論了一個遊戲，它是一個開源項目，大多數用户使用 Linux。</p><p>我不斷聽到 Linux 但當時對它還沒有興趣。然而由於這些聊天頻道（大部分在 freenode 上）談論了很多編程話題，我就開始學習 python 了。</p><p>一年後我嘗試着安裝 GNU/Linux （主要是 ubuntu）到我的新電腦（其實不新，但它是作為我的生日禮物被我得到的）。不幸的是它總是不能正常工作，原因未知，也許硬盤壞了，也許灰塵太多了。</p><p>那時我放棄自己解決這個問題，然後纏着老爸給我的電腦裝上 Ubuntu，他也無能為力，原因同上。</p><p>在追求 Linux 一段時間後，我打算拋棄 Windows，使用 Linux Mint 代替 Ubuntu，本來沒抱什麼希望，但 Linux Mint 竟然能跑起來！</p><p>於是這個系統我用了6個月。</p><p>那段時間我的一個朋友給了我一台虛擬機，跑 Ubuntu 的，我用了一年，直到我爸給了我一台服務器。</p><p>6個月後我得到一台新 PC（現在還在用）。於是起想折騰點不一樣的東西。</p><p>我打算裝 openSUSE。</p><p>我很喜歡這個系統。然後在聖誕節的時候我得到樹莓派，上面只能跑 Debian，還不能支持其它發行版。</p><p><strong>Cqz</strong>：我9歲的時候有一次玩 Windows 98，結果這貨當機了，原因未知。我沒有 Windows 安裝盤，但我爸的一本介紹編程的雜誌上有一張隨書附贈的光盤，這張光盤上剛好有 Mandrake Linux 的安裝軟件，於是我瞬間就成為了 Linux 用户。我當時還不知道自己在玩什麼，但是玩得很嗨皮。這些年我雖然在電腦上裝了多種 Windows 版本，但是 FLOSS 世界才是我的家（LCTT 譯註：FLOSS —— Free/Libre and Open Source Software，自由/開源軟件）。現在我只把 Windows 裝在虛擬機上，用來玩遊戲。</p><p><strong>Tosmarcel</strong>：15歲那年對&#39;編程&#39;這個概念很好奇，然後我開始了哈佛課程&#39;CS50&#39;，這個課程要我們安裝 Linux 虛擬機用來執行一些命令。當時我問自己為什麼 Windows 沒有這些命令？於是我 Google 了 Linux，搜索結果出現了 Ubuntu，在安裝 Ubuntu 的時候不小心把 Windows 分區給刪了。。。當時對 Linux 毫無所知，適應這個系統非常困難。我現在16歲，用 ArchLinux，不想用回 Windows，我愛 ArchLinux。</p><p><strong>Micioonthet</strong>：第一次聽説 Linux 是在我5年級的時候，當時去我一朋友家，他的筆記本裝的就是 MEPIS（Debian的一個比較老的衍生版），而不是 XP。</p><p>原來是他爸爸是個美國的社會學家，而他全家都不信任微軟。我對這些東西完全陌生，這系統完全沒有我熟悉的軟件，我很疑惑他怎麼能使用。</p><p>我13歲那年還沒有自己的筆記本電腦，而我另一位朋友總是抱怨他的電腦有多慢，所以我打算把它買下來並修好它。我花了20美元買下了這台裝着 Windows Vista 系統、跑滿病毒、完全無法使用的惠普筆記本。我不想重裝討厭的 Windows 系統，記得 Linux 是免費的，所以我刻了一張 Ubuntu 14.04 光盤，馬上把它裝起來，然後我被它的高性能給震精了。</p><p>“我的世界（Minecraft）”（由於它允許運行在 JAVA 上，所以當時它是 Linux 下為數不多的幾個遊戲之一）在 Vista 上只能跑5幀每秒，而在 Ubuntu 上能跑到25幀。</p><p>我到現在還會偶爾使用一下那台筆記本，Linux 可不會在乎你的硬件設備有多老。</p><p>之後我把我爸也拉入 Linux 行列，我們會以很低的價格買老電腦，裝上 Linux Mint 或其他輕量級發行版，這省了好多錢。</p><p><strong>Webtm</strong>：我爹每台電腦都會裝多個發行版，有幾台是 opensuse 和 Debian，他的個人電腦裝的是 Slackware。所以我記得很小的時候一直在玩 debian，但沒有投入很多精力，我用了幾年的 Windows，然後我爹問我有沒有興趣試試 debian。這是個有趣的經歷，在那之後我一直使用 debian。而現在我不用 Linux，轉投 freeBSD，5個月了，用得很開心。</p><p>完全控制自己的系統是個很奇妙的體驗。開源界有好多酷酷的軟件，我認為在自己解決一些問題並且利用這些工具解決其他事情的過程是最有趣的。當然穩定和高效也是吸引我的地方。更不用説它的保密級別了。</p><p><strong>Wyronaut</strong>：我今年18，第一次玩 Linux 是13歲，當時玩的 Ubuntu，為啥要碰 Linux？因為我想搭一個“我的世界”的服務器來和小夥伴玩遊戲，當時“我的世界”可是個新鮮玩意兒。而搭個私服需要用 Linux 系統。</p><p>當時我還是個新手，對着 Linux 的命令列有些傻眼，因為很多東西都要我自己處理。還是多虧了 Google 和維基，我成功地在多台老 PC 上部署了一些簡單的服務器，那些早已無人問津的老古董機器又能發揮餘熱了。</p><p>跑過遊戲服務器後，我又開始跑 web 服務器，先是跑了幾年 HTML，CSS 和 PHP，之後受 TheNewBoston 視頻的誤導轉到了 JAVA。</p><p>一週後放棄 JAVA 改用 Python，當時學習 Python 用的書名叫《Learn Python The Hard Way》，作者是 Zed A. Shaw。我花了兩週學完 Python，然後開始看《C++ Primer》，因為我想做遊戲開發。看到一半（大概500頁）的時候我放棄了。那個時候我有點討厭玩電腦了。</p><p>這樣中斷了一段時間之後，我決定學習 JavaScript，讀了2本書，試了4個平台，然後又不玩了。</p><p>現在到了不得不找一所學校並決定畢業後找什麼樣工作的糟糕時刻。我不想玩圖形界面編程，所以我不會進遊戲行業。我也不喜歡畫畫和建模。然後我發現了一個涉及網絡安全的專業，於是我立刻愛上它了。我挑了很多 C 語言的書來度過這個假期，並且複習了一下數學來迎接新的校園生活。</p><p>目前我玩 archlinux，不同 PC 上跑着不同任務，它們運行很穩定。</p><p>可以説 Linux 帶我進入編程的世界，而反過來，我最終在學校要學的就是 Linux。我估計會終生感謝 Linux。</p><p><strong>Linuxllc</strong>：你們可以學學像我這樣的老頭。</p><p>扔掉 Windows！扔掉 Windows！扔掉 Windows！給自己一個堅持使用 Linux 的理由，那就是完全，徹底，遠離，Windows。</p><p>我在 2003 年放棄 Windows，只用了5天就把所有電腦跑成 Linux，包括所有的外圍設備（LCTT 譯註：比如打印機？）。我不玩 Windows 裏的遊戲，只玩 Linux 裏的。</p><p><strong>Highclass</strong>：我28歲，不知道還是不是你要找的年輕人類型。</p><p>老實説我對電腦挺感興趣的，當我還沒接觸&#39;自由軟件哲學&#39;的時候，我認為 free 是免費的意思。我也不認為命令列界面很讓人難以接受，因為我小時候就接觸過 DOS 系統。</p><p>我第一個發行版是 Mandrake，在我11歲還是12歲那年我把家裏的電腦弄得亂七八糟，然後我一直折騰那台電腦，試着讓我自己的技能提升一個台階。現在我在一家公司全職使用 Linux。（請允許我聳個肩）。</p><p><strong>Matto</strong>：我的電腦是舊貨市場淘回來的，裝 XP，跑得慢，於是我想換個系統。Google 了一下，發現 Ubuntu。當年我15、6歲，現在23了，就職的公司內部使用 Linux。</p>",38)),i("p",null,[o(u,{href:"https://www.reddit.com/r/linux/comments/3hb2sr/question_for_younger_users_why_did_you_start/"},{default:l(()=>[...n[4]||(n[4]=[t("更多評論移步 Reddit",-1)])]),_:1})])]),n[33]||(n[33]=i("h3",{id:"ibm-的-linux-大型機",tabindex:"-1"},[t("IBM 的 Linux 大型機 "),i("a",{class:"header-anchor",href:"#ibm-的-linux-大型機","aria-label":"Permalink to “IBM 的 Linux 大型機”"},"​")],-1)),n[34]||(n[34]=i("p",null,"IBM 很久前就用 Linux 了。現在這家公司退推出一款機器專門使用 Ubuntu，機器名叫 LinuxOne。",-1)),n[35]||(n[35]=i("p",null,"Ron Miller 在 TecchCrunch Blog上説：",-1)),i("blockquote",null,[n[7]||(n[7]=i("p",null,"新的大型機包括兩款機型，都是以企鵝名稱命名的（Linux 的吉祥物就是一隻企鵝，懂18摸的命名用意了沒？）第一款叫帝企鵝，使用 IBM z13 機型，我們早在1月份就介紹過了。另一款稍微小一點，名叫跳巖企鵝，供入門級買家使用。",-1)),n[8]||(n[8]=i("p",null,"也許你會以為大型機就像恐龍一樣早就滅絕了，但世界上許多大型機構中都還在使用它們，它們還健在。作為發展雲技術戰略的一部分，數據分析與安全有望於提升 Ubuntu 大型機的市場，這種大型機能提供一系列開源的企業級軟件，比如 Apache Spark，Node.js，MongoDB，MariaDB，PostgreSQL 和 Chef。",-1)),n[9]||(n[9]=i("p",null,"大型機還會存在於客户預置的數據中心中，但是市場的大小取決於會有多少客户使用這種類似於雲服務的系統。Mauri 解釋道，IBM 正在尋求增加大型機銷量的途徑，與 Canonical 公司合作，鼓勵使用開源工具，都能為大型機打開一個小的，卻能賺錢的市場。",-1)),i("p",null,[o(u,{href:"http://techcrunch.com/2015/08/16/ibm-teams-with-canonical-on-linux-mainframe/"},{default:l(()=>[...n[6]||(n[6]=[t("詳情移步 TechCrunch",-1)])]),_:1})])]),n[36]||(n[36]=i("h3",{id:"你為什麼要放棄-windows10-而選擇-linux",tabindex:"-1"},[t("你為什麼要放棄 Windows10 而選擇 Linux "),i("a",{class:"header-anchor",href:"#你為什麼要放棄-windows10-而選擇-linux","aria-label":"Permalink to “你為什麼要放棄 Windows10 而選擇 Linux”"},"​")],-1)),n[37]||(n[37]=i("p",null,"自從 Windows10 出來以後，各種媒體都報道過它的隱藏間諜功能。ZDNet 列出了一些放棄 Windows10 的理由。",-1)),n[38]||(n[38]=i("p",null,"SJVN 在 ZDNet 的報告：",-1)),i("blockquote",null,[n[11]||(n[11]=i("p",null,"你試試關掉 Windows10 的數據分享功能，壞消息來了：window10 會繼續把你的數據分享給微軟公司。請選擇 Linux 吧。",-1)),n[12]||(n[12]=i("p",null,"你可以有很多方法不讓 Windows10 泄露你的秘密，但你不能阻止它交談。Cortana，win10 小娜，語音助手，就算你把她關了，她也會把數據發給微軟公司。這些數據包括你的電腦 ID，微軟用它來識別你的 PC 機。",-1)),n[13]||(n[13]=i("p",null,"所以如果這些泄密給你帶來了煩惱，你可以使用老版本 Windows7，或者換到 Linux。然而，當 Windows7 不再提供技術支持的那天到來，如果你還想保留隱私，最終你還是隻能選擇 Linux。",-1)),n[14]||(n[14]=i("p",null,"這裏還有些小眾的桌面系統能保護你的隱私，比如 BSD 家族的 FreeBSD，PCBSD，NetBSD，eComStation，OS/2。但是，最好的選擇還是 Linux，它提供最低的學習曲線。",-1)),i("p",null,[o(u,{href:"http://www.zdnet.com/article/sick-of-windows-spying-on-you-go-linux/"},{default:l(()=>[...n[10]||(n[10]=[t("詳情移步 ZDNet",-1)])]),_:1})])]),n[39]||(n[39]=i("hr",null,null,-1)),i("p",null,[n[16]||(n[16]=t("via: ",-1)),o(u,{href:"http://www.itworld.com/article/2972587/linux/why-did-you-start-using-linux.html"},{default:l(()=>[...n[15]||(n[15]=[t("http://www.itworld.com/article/2972587/linux/why-did-you-start-using-linux.html",-1)])]),_:1})]),i("p",null,[n[20]||(n[20]=t("作者：",-1)),o(u,{href:"http://www.itworld.com/author/Jim-Lynch/"},{default:l(()=>[...n[17]||(n[17]=[t("Jim Lynch",-1)])]),_:1}),n[21]||(n[21]=t(" 譯者：",-1)),o(u,{href:"https://github.com/bazz2"},{default:l(()=>[...n[18]||(n[18]=[t("bazz2",-1)])]),_:1}),n[22]||(n[22]=t(" 校對：",-1)),o(u,{href:"https://github.com/wxy"},{default:l(()=>[...n[19]||(n[19]=[t("wxy",-1)])]),_:1})]),i("p",null,[n[25]||(n[25]=t("本文由 ",-1)),o(u,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...n[23]||(n[23]=[t("LCTT",-1)])]),_:1}),n[26]||(n[26]=t(" 原創翻譯，",-1)),o(u,{href:"https://linux.cn/"},{default:l(()=>[...n[24]||(n[24]=[t("Linux中國",-1)])]),_:1}),n[27]||(n[27]=t(" 榮譽推出",-1))])])}const W=r(x,[["render",L]]);export{T as __pageData,W as default};
